export type HorsePickerProps = {
    horses: Array<Pick<Horse, "id" | "name" | "breed">>;
};

export async function readHorsePicker(horses: Horse[]): Promise<HorsePickerProps> {
    return {
        horses: await Promise.all(
            horses.map(async (record) => {
                return {
                    id: record.id,
                    name: record.name,
                    breed: record.breed,
                };
            }),
        ),
    };
}

